/**
 * Domain types for the Storage UI kit.
 *
 * These mirror the real Storage GraphQL schema so wiring a data layer
 * (Phase 2) is a matter of mapping query results onto these shapes — no
 * component prop changes required.
 */

export type BucketVisibility = 'public' | 'private' | 'temp';

export interface StorageBucket {
	id: string;
	key: string;
	/** Friendly label; the key shows when omitted. */
	name?: string | null;
	visibility: BucketVisibility;
	isPublic: boolean;
	allowCustomKeys: boolean;
	allowedMimeTypes?: string[];
	maxFileSize?: number | null;
	allowedOrigins?: string[];
	description?: string | null;
	provisioned?: boolean;
	objectCount?: number | null;
	createdAt?: string;
}

export type StorageObjectStatus = 'requested' | 'uploaded' | 'processed';

export interface StorageObject {
	id: string;
	bucketId: string;
	key: string;
	filename: string | null;
	mimeType: string;
	size: number;
	isPublic: boolean;
	status?: StorageObjectStatus;
	createdAt: string;
	updatedAt?: string;
	downloadUrl?: string | null;
	/** Folders list alongside files in a prefix view and open with `onOpenFolder`. Default: `file`. */
	kind?: 'file' | 'folder';
	/** Preformatted size, shown instead of `size` when the host only has a label. */
	sizeLabel?: string;
}

export type UploadStatus = 'queued' | 'uploading' | 'done' | 'error';

export interface UploadItem {
	id: string;
	filename: string;
	size: number;
	progress: number;
	status: UploadStatus;
	error?: string;
}

export type ObjectSortColumn = 'filename' | 'size' | 'createdAt' | 'mimeType';

export type ObjectSort = {
	column: ObjectSortColumn;
	direction: 'asc' | 'desc';
};

/**
 * Pure presentational helpers for the Storage UI kit.
 *
 * No side effects, no I/O — safe to import anywhere (including non-'use client'
 * leaf components).
 */

import type { StorageBucket, StorageObject } from '@/components/ui/storage/types';

/** Humanize a byte count, e.g. 1536 -> "1.5 KB". Missing, negative and non-finite values read as an em dash. */
export function humanizeBytes(bytes: number | null | undefined): string {
	if (bytes == null || !Number.isFinite(bytes) || bytes < 0) return '—';
	if (bytes === 0) return '0 B';

	const units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB'];
	let value = bytes;
	let exponent = 0;
	while (value >= 1024 && exponent < units.length - 1) {
		value /= 1024;
		exponent += 1;
	}
	// Rounding can land on the next unit's boundary ("1024.0 KB", "1024 B"): carry into that unit instead.
	const rounded = exponent === 0 ? Math.round(value) : Number(value.toFixed(1));
	if (rounded >= 1024 && exponent < units.length - 1) {
		value /= 1024;
		exponent += 1;
	}
	// Whole bytes show no decimals (round any fractional byte count); larger units show one.
	const formatted = exponent === 0 ? String(Math.round(value)) : value.toFixed(1);
	return `${formatted} ${units[exponent]}`;
}

export { formatCount } from '@/lib/intl';

// Built once: `toLocaleDateString` creates a formatter on every call, which adds up across table rows.
const DATE = new Intl.DateTimeFormat(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
const DATE_TIME = new Intl.DateTimeFormat(undefined, { year: 'numeric', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });

/**
 * Format an ISO timestamp as a compact, locale date — e.g. "Jun 24, 2026". Unparseable values and the Unix
 * epoch (`1970-01-01T00:00:00Z`, what a zeroed or defaulted timestamp becomes) read as an em dash.
 */
export function formatDate(iso: string | null | undefined): string {
	if (!iso) return '—';
	const time = Date.parse(iso);
	return Number.isNaN(time) || time === 0 ? '—' : DATE.format(time);
}

/** Format an ISO timestamp with date + time — used in the detail sheet. */
export function formatDateTime(iso: string | null | undefined): string {
	if (!iso) return '—';
	const time = Date.parse(iso);
	return Number.isNaN(time) || time === 0 ? '—' : DATE_TIME.format(time);
}

/**
 * Short, human-friendly label for a MIME type — e.g.
 * "image/png" -> "PNG", "application/pdf" -> "PDF",
 * "application/vnd.openxmlformats-officedocument.wordprocessingml.document" -> "DOCX".
 */
export function shortMimeLabel(mimeType: string | null | undefined): string {
	if (!mimeType) return '—';
	const lower = mimeType.toLowerCase();

	const known: Record<string, string> = {
		'application/pdf': 'PDF',
		'application/zip': 'ZIP',
		'application/x-zip-compressed': 'ZIP',
		'application/gzip': 'GZIP',
		'application/x-tar': 'TAR',
		'application/json': 'JSON',
		'application/msword': 'DOC',
		'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'DOCX',
		'application/vnd.ms-excel': 'XLS',
		'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'XLSX',
		'application/vnd.ms-powerpoint': 'PPT',
		'application/vnd.openxmlformats-officedocument.presentationml.presentation': 'PPTX',
		'text/csv': 'CSV',
		'text/plain': 'TXT',
		'text/markdown': 'MD',
		'application/vnd.oasis.opendocument.text': 'ODT',
		'application/vnd.oasis.opendocument.spreadsheet': 'ODS',
		'application/vnd.oasis.opendocument.presentation': 'ODP',
		'application/vnd.android.package-archive': 'APK',
		'application/x-7z-compressed': '7Z',
		'application/x-rar-compressed': 'RAR',
	};
	if (known[lower]) return known[lower];

	// Fall back to the subtype: "image/svg+xml" -> "SVG", "video/mp4" -> "MP4".
	const subtype = lower.split('/')[1] ?? lower;
	let base = subtype.split('+')[0].replace(/^x-/, '');
	// Vendor trees ("vnd.google-apps.spreadsheet") are namespaces: the last segment is the format.
	if (base.startsWith('vnd.')) base = base.split('.').pop() || base;
	return base.toUpperCase();
}

/** Best display name for an object: filename, falling back to its key. */
export function objectDisplayName(object: Pick<StorageObject, 'filename' | 'key'>): string {
	return object.filename?.trim() || object.key;
}

/** Best display name for a bucket: its friendly name, falling back to its key. */
export function bucketDisplayName(bucket: Pick<StorageBucket, 'key'> & { name?: string | null }): string {
	return bucket.name?.trim() || bucket.key;
}

export type FileCategory = 'image' | 'video' | 'audio' | 'document' | 'spreadsheet' | 'archive' | 'text' | 'folder' | 'other';

const DOCUMENT_TYPES = new Set([
	'application/pdf',
	'application/msword',
	'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
	'application/vnd.ms-powerpoint',
	'application/vnd.openxmlformats-officedocument.presentationml.presentation',
]);
const SPREADSHEET_TYPES = new Set([
	'text/csv',
	'application/vnd.ms-excel',
	'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
]);
const ARCHIVE_TYPES = new Set([
	'application/zip',
	'application/x-zip-compressed',
	'application/gzip',
	'application/x-tar',
	'application/x-7z-compressed',
	'application/x-rar-compressed',
]);

/** Broad family of a MIME type, for choosing an icon and its tint. */
export function fileCategory(mimeType: string | null | undefined): FileCategory {
	if (!mimeType) return 'other';
	const lower = mimeType.toLowerCase();
	if (lower.startsWith('image/')) return 'image';
	if (lower.startsWith('video/')) return 'video';
	if (lower.startsWith('audio/')) return 'audio';
	if (DOCUMENT_TYPES.has(lower)) return 'document';
	if (SPREADSHEET_TYPES.has(lower)) return 'spreadsheet';
	if (ARCHIVE_TYPES.has(lower)) return 'archive';
	if (lower.startsWith('text/') || lower === 'application/json') return 'text';
	return 'other';
}

/** The folder part of an object key, e.g. "launch/cover.png" → "launch/". */
export function keyFolder(key: string): string {
	const slash = key.lastIndexOf('/');
	return slash > 0 ? key.slice(0, slash + 1) : '';
}

import {
	FileArchiveIcon,
	FileAudioIcon,
	FileCodeIcon,
	FileIcon,
	FileImageIcon,
	FileSpreadsheetIcon,
	FileTextIcon,
	FileVideoIcon,
	FolderIcon,
} from 'lucide-react';
import type { LucideIcon } from 'lucide-react';

import { cn } from '@/lib/utils';
import type { Tone } from '@/components/ui/workspace-kit/primitives';
import { IconTile } from '@/components/ui/workspace-kit/surface';
import { fileCategory, type FileCategory } from '@/components/ui/storage/utils';

const CATEGORY: Record<FileCategory, { icon: LucideIcon; tone: Tone }> = {
	image: { icon: FileImageIcon, tone: 'info' },
	video: { icon: FileVideoIcon, tone: 'violet' },
	audio: { icon: FileAudioIcon, tone: 'violet' },
	document: { icon: FileTextIcon, tone: 'danger' },
	spreadsheet: { icon: FileSpreadsheetIcon, tone: 'success' },
	archive: { icon: FileArchiveIcon, tone: 'amber' },
	text: { icon: FileCodeIcon, tone: 'neutral' },
	folder: { icon: FolderIcon, tone: 'primary' },
	other: { icon: FileIcon, tone: 'neutral' },
};

interface FileTypeIconProps {
	/** The object's MIME type, e.g. "image/png". */
	mimeType: string | null | undefined;
	className?: string;
	/** Forwarded to the underlying svg as the accessible label, if any. */
	'aria-label'?: string;
}

/**
 * `FileTypeIcon` — a single lucide glyph chosen from a file's MIME type.
 * Defaults to a muted foreground tint; override via `className`.
 */
export function FileTypeIcon({ mimeType, className, ...props }: FileTypeIconProps) {
	const Icon = CATEGORY[fileCategory(mimeType)].icon;
	return <Icon aria-hidden className={cn('size-4 shrink-0 text-muted-foreground', className)} {...props} />;
}

interface FileGlyphProps {
	mimeType?: string | null;
	/** Folders get their own glyph regardless of MIME type. */
	kind?: 'file' | 'folder';
	className?: string;
}

/**
 * `FileGlyph` — the file's icon on a small tile tinted by its family (images
 * blue, documents red, spreadsheets green, archives amber), so a list can be
 * scanned by type before reading names.
 */
export function FileGlyph({ mimeType, kind = 'file', className }: FileGlyphProps) {
	const { icon, tone } = CATEGORY[kind === 'folder' ? 'folder' : fileCategory(mimeType)];
	return <IconTile icon={icon} tone={tone} className={className} />;
}

import { ClockIcon, GlobeIcon, LockIcon } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';

import type { BadgeProps } from '@/components/ui/badge';
import { ToneBadge, type Tone } from '@/components/ui/workspace-kit/primitives';
import type { BucketVisibility, StorageObjectStatus } from '@/components/ui/storage/types';

interface VisibilityBadgeProps {
	visibility: BucketVisibility;
	/** Kept for compatibility; the badge has one size. */
	size?: BadgeProps['size'];
	className?: string;
	/** Hide the leading icon (e.g. in very dense rows). */
	hideIcon?: boolean;
}

export const VISIBILITY: Record<BucketVisibility, { label: string; icon: LucideIcon; tone: Tone; hint: string }> = {
	public: { label: 'Public', icon: GlobeIcon, tone: 'info', hint: 'Anyone with the link can read objects.' },
	private: { label: 'Private', icon: LockIcon, tone: 'neutral', hint: 'Only authorized requests can read objects.' },
	temp: { label: 'Temp', icon: ClockIcon, tone: 'warning', hint: 'Short-lived objects, cleaned up automatically.' },
};

/**
 * `VisibilityBadge` — a bucket's visibility as a small tinted label. Private
 * stays neutral, public reads as information, and temp warns that content
 * expires.
 */
export function VisibilityBadge({ visibility, className, hideIcon }: VisibilityBadgeProps) {
	const config = VISIBILITY[visibility] ?? VISIBILITY.private;
	const Icon = config.icon;
	return (
		<ToneBadge tone={config.tone} className={className}>
			{hideIcon ? null : <Icon aria-hidden="true" />}
			{config.label}
		</ToneBadge>
	);
}

interface ObjectStatusBadgeProps {
	status: StorageObjectStatus;
	/** Kept for compatibility; the badge has one size. */
	size?: BadgeProps['size'];
	className?: string;
}

const STATUS: Record<StorageObjectStatus, { label: string; tone: Tone }> = {
	requested: { label: 'Requested', tone: 'neutral' },
	uploaded: { label: 'Uploaded', tone: 'info' },
	processed: { label: 'Processed', tone: 'success' },
};

/** `ObjectStatusBadge` — lifecycle status for a stored object; `processed` reads as done. */
export function ObjectStatusBadge({ status, className }: ObjectStatusBadgeProps) {
	const config = STATUS[status];
	return (
		<ToneBadge tone={config.tone} className={className}>
			{config.label}
		</ToneBadge>
	);
}

'use client';

import { ChevronRightIcon, HardDriveIcon } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { focusRingClass, scrollRowClass } from '@/components/ui/workspace-kit/primitives';

/** A single path segment inside a bucket (folder-style). */
export interface StorageBreadcrumbSegment {
	/** Label rendered for the segment. */
	label: string;
	/** Full prefix path this segment navigates to (e.g. "images/avatars/"). */
	path: string;
}

interface StorageBreadcrumbProps {
	/** The bucket name shown as the root crumb. */
	bucketKey: string;
	/** Folder segments after the bucket root. Empty = just the bucket. */
	segments?: StorageBreadcrumbSegment[];
	/**
	 * Navigate callback. `path` is the segment's prefix, or `null` for the
	 * bucket root crumb. Without it every crumb is plain text.
	 */
	onNavigate?: (path: string | null) => void;
	/** Disable navigation, e.g. while a folder is loading. */
	disabled?: boolean;
	className?: string;
}

const CRUMB = 'inline-flex h-6 min-w-0 max-w-48 items-center gap-1.5 rounded-md px-1.5';

/**
 * `StorageBreadcrumb` — the bucket root and folder segments as quiet, compact
 * crumbs. The last crumb is the current location; earlier ones navigate
 * when `onNavigate` is set. Scrolls sideways instead of wrapping.
 */
export function StorageBreadcrumb({ bucketKey, segments = [], onNavigate, disabled = false, className }: StorageBreadcrumbProps) {
	const crumbs = [{ label: bucketKey, path: null as string | null }, ...segments.map((segment) => ({ label: segment.label, path: segment.path as string | null }))];
	const navRef = React.useRef<HTMLElement>(null);
	const location = crumbs[crumbs.length - 1]?.path ?? bucketKey;

	// The row scrolls sideways, and the crumb that matters is the last one: bring it into view whenever the path changes.
	React.useEffect(() => {
		const nav = navRef.current;
		const current = nav?.querySelector<HTMLElement>('[aria-current="location"]');
		if (!nav || !current) return;
		const frame = nav.getBoundingClientRect();
		const box = current.getBoundingClientRect();
		if (box.right > frame.right) nav.scrollBy({ left: box.right - frame.right + 8 });
		else if (box.left < frame.left) nav.scrollBy({ left: box.left - frame.left - 8 });
	}, [location, crumbs.length]);

	return (
		<nav ref={navRef} aria-label="Folder path" className={cn(scrollRowClass, 'min-w-0', className)}>
			<ol className="flex w-max items-center gap-0.5 text-[0.8125rem]">
				{crumbs.map((crumb, index) => {
					const last = index === crumbs.length - 1;
					const content = (
						<>
							{index === 0 ? <HardDriveIcon aria-hidden="true" className="size-3.5 shrink-0" /> : null}
							<span className="truncate">{crumb.label}</span>
						</>
					);
					return (
						<li key={crumb.path ?? '__root__'} className="flex min-w-0 items-center gap-0.5">
							{index > 0 ? <ChevronRightIcon aria-hidden="true" className="size-3.5 shrink-0 text-subtle-foreground" /> : null}
							{last || !onNavigate ? (
								<span aria-current={last ? 'location' : undefined} className={cn(CRUMB, last ? 'font-medium text-foreground' : 'text-muted-foreground')} title={crumb.label}>
									{content}
								</span>
							) : (
								<button
									type="button"
									disabled={disabled}
									onClick={() => onNavigate(crumb.path)}
									title={crumb.label}
									className={cn(CRUMB, 'cursor-pointer text-muted-foreground hover:bg-overlay-hover hover:text-foreground disabled:cursor-not-allowed disabled:opacity-60', focusRingClass)}
								>
									{content}
								</button>
							)}
						</li>
					);
				})}
			</ol>
		</nav>
	);
}

'use client';

import { ArrowDownWideNarrowIcon, ArrowUpNarrowWideIcon, Loader2Icon, Trash2Icon, UploadIcon, XIcon } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import {
	DropdownMenu,
	DropdownMenuContent,
	DropdownMenuLabel,
	DropdownMenuRadioGroup,
	DropdownMenuRadioItem,
	DropdownMenuSeparator,
	DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { enterClass, focusRingClass, pressClass, SearchField } from '@/components/ui/workspace-kit/primitives';
import type { ObjectSort, ObjectSortColumn } from '@/components/ui/storage/types';
import { formatCount } from '@/components/ui/storage/utils';

const SORT_COLUMNS: { value: ObjectSortColumn; label: string }[] = [
	{ value: 'filename', label: 'Name' },
	{ value: 'size', label: 'Size' },
	{ value: 'createdAt', label: 'Modified' },
	{ value: 'mimeType', label: 'Type' },
];

type BulkDeleteProgress = { done: number; total: number; failed: string[] };

interface ObjectSelectionBarProps {
	selectedCount: number;
	/** Signals intent to delete the selection; the parent binds the ids and confirms. */
	onBulkDelete?: () => void;
	/** In-flight bulk delete: shows "Deleting N/M" and disables the actions; failed ids surface as a note. */
	bulkDeleteProgress?: BulkDeleteProgress;
	onClearSelection?: () => void;
	/** Float over the bottom of the list instead of sitting inline. */
	floating?: boolean;
	/** Locale for the counts (for example `de-DE`). Default: `en-US`, so the server and the browser agree. */
	locale?: string;
	className?: string;
}

/**
 * `ObjectSelectionBar` — what to do with the selected files: a count, a
 * destructive Delete, and Clear. Announces the selection and bulk-delete
 * progress to screen readers; renders only the announcer when nothing is
 * selected.
 */
export function ObjectSelectionBar({ selectedCount, onBulkDelete, bulkDeleteProgress, onClearSelection, floating = false, locale, className }: ObjectSelectionBarProps) {
	const deleting = bulkDeleteProgress != null && bulkDeleteProgress.done < bulkDeleteProgress.total;
	const failed = bulkDeleteProgress?.failed.length ?? 0;
	const noun = selectedCount === 1 ? 'file' : 'files';
	const done = bulkDeleteProgress ? formatCount(bulkDeleteProgress.done, locale) : '';
	const total = bulkDeleteProgress ? formatCount(bulkDeleteProgress.total, locale) : '';
	const progress = bulkDeleteProgress
		? deleting
			? ` Deleting ${done} of ${total}.`
			: ` Deletion finished: ${done} of ${total} processed.`
		: '';
	const status =
		selectedCount > 0
			? `${formatCount(selectedCount, locale)} ${noun} selected.${progress}${failed > 0 ? ` ${formatCount(failed, locale)} failed.` : ''}`
			: 'No files selected.';

	return (
		<>
			<span className="sr-only" role="status" aria-live="polite" aria-atomic="true">
				{status}
			</span>
			{selectedCount > 0 ? (
				<div
					className={cn(
						// Wraps rather than spilling out of the pill when counts and the failure note get long.
						'flex min-h-9 flex-wrap items-center gap-x-1 rounded-lg py-0.5 pe-1 ps-3 text-[0.8125rem]',
						floating ? cn('bg-card shadow-card-lg', enterClass) : 'bg-muted/60',
						className,
					)}
				>
					<span className="font-medium whitespace-nowrap text-foreground tabular-nums">{formatCount(selectedCount, locale)} selected</span>
					{failed > 0 ? <span className="text-xs whitespace-nowrap text-destructive tabular-nums">· {formatCount(failed, locale)} failed</span> : null}
					<span aria-hidden="true" className="mx-1.5 h-4 w-px bg-border" />
					{onBulkDelete ? (
						<button
							type="button"
							onClick={onBulkDelete}
							disabled={deleting}
							className={cn(
								'inline-flex h-7 cursor-pointer items-center gap-1.5 rounded-md px-2 text-destructive hover:bg-destructive/10 disabled:cursor-not-allowed disabled:opacity-60',
								pressClass,
								focusRingClass,
							)}
						>
							{deleting ? <Loader2Icon aria-hidden="true" className="size-3.5 motion-safe:animate-spin" /> : <Trash2Icon aria-hidden="true" className="size-3.5" />}
							<span className="whitespace-nowrap tabular-nums">{deleting ? `Deleting ${done}/${total}` : 'Delete'}</span>
						</button>
					) : null}
					{onClearSelection ? (
						<button
							type="button"
							onClick={onClearSelection}
							disabled={deleting}
							aria-label="Clear selection"
							className={cn(
								'grid size-7 cursor-pointer place-items-center rounded-md text-muted-foreground hover:bg-overlay-hover hover:text-foreground disabled:cursor-not-allowed disabled:opacity-60',
								pressClass,
								focusRingClass,
							)}
						>
							<XIcon aria-hidden="true" className="size-3.5" />
						</button>
					) : null}
				</div>
			) : null}
		</>
	);
}

interface ObjectToolbarProps {
	query: string;
	onQueryChange: (query: string) => void;
	sort: ObjectSort;
	onSortChange: (sort: ObjectSort) => void;
	onUpload?: () => void;
	/** Number of currently selected objects. >0 swaps to the selection bar. */
	selectedCount?: number;
	/** Signals intent to delete the selection; the parent binds the ids + confirms. */
	onBulkDelete?: () => void;
	/**
	 * Progress for an in-flight bulk delete: while set, the Delete button shows a
	 * "Deleting N/M" count and is disabled; any failed ids surface as a note.
	 */
	bulkDeleteProgress?: BulkDeleteProgress;
	onClearSelection?: () => void;
	/** Locale for the counts (for example `de-DE`). Default: `en-US`. */
	locale?: string;
	className?: string;
}

/** Compact sort menu: the column and direction, as one control. */
export function ObjectSortMenu({ sort, onSortChange }: Pick<ObjectToolbarProps, 'sort' | 'onSortChange'>) {
	const active = SORT_COLUMNS.find((column) => column.value === sort.column);
	const DirectionIcon = sort.direction === 'asc' ? ArrowUpNarrowWideIcon : ArrowDownWideNarrowIcon;
	return (
		<DropdownMenu>
			<DropdownMenuTrigger
				aria-label={`Sort by ${active?.label ?? 'column'}, ${sort.direction === 'asc' ? 'ascending' : 'descending'}`}
				className={cn(
					'inline-flex h-7 shrink-0 cursor-pointer items-center gap-1.5 rounded-md border border-border bg-card px-2 text-[0.8125rem] text-foreground shadow-2xs hover:bg-muted data-[popup-open]:bg-muted',
					pressClass,
					focusRingClass,
				)}
			>
				<DirectionIcon aria-hidden="true" className="size-3.5 text-muted-foreground" />
				<span aria-hidden="true" className="hidden @md/view:inline">
					{active?.label ?? 'Sort'}
				</span>
			</DropdownMenuTrigger>
			<DropdownMenuContent align="end" className="min-w-44">
				<DropdownMenuLabel>Sort by</DropdownMenuLabel>
				<DropdownMenuRadioGroup value={sort.column} onValueChange={(value) => onSortChange({ ...sort, column: value as ObjectSortColumn })}>
					{SORT_COLUMNS.map((column) => (
						<DropdownMenuRadioItem key={column.value} value={column.value}>
							{column.label}
						</DropdownMenuRadioItem>
					))}
				</DropdownMenuRadioGroup>
				<DropdownMenuSeparator />
				<DropdownMenuLabel>Direction</DropdownMenuLabel>
				<DropdownMenuRadioGroup value={sort.direction} onValueChange={(value) => onSortChange({ ...sort, direction: value as ObjectSort['direction'] })}>
					<DropdownMenuRadioItem value="asc">Ascending</DropdownMenuRadioItem>
					<DropdownMenuRadioItem value="desc">Descending</DropdownMenuRadioItem>
				</DropdownMenuRadioGroup>
			</DropdownMenuContent>
		</DropdownMenu>
	);
}

/**
 * `ObjectToolbar` — search, sort, and upload. When `selectedCount > 0` it
 * swaps to the selection bar (count, destructive Delete, Clear). Fully
 * controlled; Delete only signals intent, so route it through a confirmation.
 */
export function ObjectToolbar({
	query,
	onQueryChange,
	sort,
	onSortChange,
	onUpload,
	selectedCount = 0,
	onBulkDelete,
	bulkDeleteProgress,
	onClearSelection,
	locale,
	className,
}: ObjectToolbarProps) {
	if (selectedCount > 0) {
		return (
			<ObjectSelectionBar
				selectedCount={selectedCount}
				onBulkDelete={onBulkDelete}
				bulkDeleteProgress={bulkDeleteProgress}
				onClearSelection={onClearSelection}
				locale={locale}
				className={className}
			/>
		);
	}

	return (
		<>
			<ObjectSelectionBar selectedCount={0} />
			<div className={cn('flex items-center gap-2', className)}>
				<SearchField
					label="Search files"
					placeholder="Search files"
					value={query}
					onChange={(event) => onQueryChange(event.target.value)}
					className="w-full min-w-0 @md/view:w-56"
				/>
				<ObjectSortMenu sort={sort} onSortChange={onSortChange} />
				{onUpload ? (
					<Button aria-label="Upload files" size="sm" className="h-7 shrink-0" onClick={onUpload}>
						<UploadIcon aria-hidden="true" data-icon="inline-start" />
						<span className="hidden @md/view:inline">Upload</span>
					</Button>
				) : null}
			</div>
		</>
	);
}
